mapper.select:
SELECT prefix, claimed_pi FROM (
  SELECT id, prefix, claimed_pi FROM sn_rule_version WHERE prefix LIKE #{like} AND prefix <> #{prefix}

    UNION ALL SELECT id, prefix, claimed_pi FROM sn_rule_version WHERE prefix IN
    #{h}

) o ORDER BY id LIMIT 1

SELECT * FROM sn_rule_version
WHERE rule_id IN #{i}
ORDER BY rule_id, version DESC

SELECT rule_id, pi_no v FROM sn_pi_rule WHERE rule_id IN
#{i}
ORDER BY pi_no

SELECT * FROM sn_rule WHERE 1=1 
AND category_scope = #{category}
AND category_value = #{value}

  AND (rule_code LIKE #{like} OR rule_name LIKE #{like} OR category_value LIKE #{like} OR id IN
    (SELECT rule_id FROM sn_rule_version WHERE claimed_pi LIKE #{like}))

ORDER BY category_scope = 'PI' DESC, category_value ASC, rule_code ASC

mapper.update:
UPDATE sn_rule_version SET prefix = #{entity.prefix}, suffix = #{entity.suffix}, base = #{entity.base},
  seq_len = #{entity.seqLen}, charset = #{entity.charset}, with_length = #{entity.withLength},
  length_pad = #{entity.lengthPad}, length_sep_before = #{entity.lengthSepBefore},
  length_sep_after = #{entity.lengthSepAfter}, with_unit = #{entity.withUnit}, updated_at = #{entity.updatedAt}
WHERE id = #{entity.id}

UPDATE sn_rule SET rule_name = #{name}, category_scope = #{scope}, category_value = #{value},
  current_version = #{version}, updated_by = #{by}, updated_at = #{now}
WHERE id = #{id}
